<?php
if (isset($_SERVER['SCRIPT_FILENAME']) && realpath($_SERVER['SCRIPT_FILENAME']) === __FILE__) { http_response_code(404); exit; }   // include-only: never executable directly
/**
 * Affiliate dashboard and revenue-opportunity report (Phase 7E). RECORDED data only: outbound/affiliate clicks come from the existing click analytics (adm_tool_daily),
 * commissions from aff_commission, partnerships and links from their tables. No earnings are estimated or projected. Money stays per currency (never converted or summed
 * across currencies). A state is never silently zero: null = unavailable (storage missing), empty = nothing recorded yet, a number (including 0) = recorded.
 */
require_once __DIR__ . '/aff_core.php';

/** @return ?array<string,array{views:int,outbound:int,affiliate:int}> null when the click analytics storage is not installed; [] when installed but nothing recorded in the range. */
function aff_tool_clicks(PDO $pdo, string $from, string $to): ?array {
  try { $pdo->query('SELECT 1 FROM adm_tool_daily LIMIT 1'); } catch (Throwable $e) { return null; }
  $s = $pdo->prepare('SELECT tool_slug, SUM(tool_views) v, SUM(outbound_clicks) o, SUM(affiliate_clicks) a FROM adm_tool_daily WHERE day BETWEEN ? AND ? GROUP BY tool_slug'); $s->execute([$from, $to]); $o = [];
  foreach ($s->fetchAll(PDO::FETCH_ASSOC) as $r) $o[(string)$r['tool_slug']] = ['views' => (int)$r['v'], 'outbound' => (int)$r['o'], 'affiliate' => (int)$r['a']]; return $o;
}
function aff_period(int $days, ?int $nowTs = null): array { $days = in_array($days, [30, 90, 180, 365], true) ? $days : 90; $to = gmdate('Y-m-d', $nowTs ?? time()); return [gmdate('Y-m-d', strtotime($to . ' UTC') - ($days - 1) * 86400), $to, $days]; }

function aff_dashboard(PDO $pdo, int $days = 90, ?int $nowTs = null): array {
  [$from, $to, $days] = aff_period($days, $nowTs); $cat = aff_catalogue(); $d = ['ready' => aff_ready($pdo), 'from' => $from, 'to' => $to, 'days' => $days, 'catalogue' => count($cat)];
  if (!$d['ready']) return $d + ['partners' => null, 'approved' => null, 'pending' => null, 'monetized' => null, 'unmonetized' => null, 'clicks' => null, 'conversions' => null, 'rate' => null, 'money' => [], 'epc' => [], 'top_tools' => [], 'top_networks' => [], 'trend' => [], 'by_status' => []];
  $by = array_fill_keys(array_keys(aff_statuses()), 0); foreach ($pdo->query('SELECT status, COUNT(*) n FROM aff_partner GROUP BY status')->fetchAll(PDO::FETCH_KEY_PAIR) as $k => $n) $by[$k] = (int)$n; $total = array_sum($by);
  $mon = array_map('strval', $pdo->query("SELECT DISTINCT l.tool_slug FROM aff_link l JOIN aff_partner p ON p.id = l.partner_id WHERE l.status = 'active' AND p.status IN ('approved','active')")->fetchAll(PDO::FETCH_COLUMN)); $legacy = 0; foreach ($cat as $id => $t) if (!in_array((string)$id, $mon, true) && trim((string)($t['affiliate'] ?? '')) !== '') $legacy++;
  $clicksAll = aff_tool_clicks($pdo, $from, $to); $clicks = $clicksAll === null ? null : ['outbound' => array_sum(array_column($clicksAll, 'outbound')), 'affiliate' => array_sum(array_column($clicksAll, 'affiliate'))];
  $money = []; foreach ($pdo->query('SELECT currency, status, COUNT(*) n, SUM(amount_minor) s FROM aff_commission GROUP BY currency, status')->fetchAll(PDO::FETCH_ASSOC) as $r) { $c = $r['currency']; $money[$c] = $money[$c] ?? ['pending' => 0, 'approved' => 0, 'received' => 0, 'rejected' => 0, 'reversed' => 0, 'count' => 0]; $k = $r['status'] === 'paid' ? 'received' : $r['status']; $money[$c][$k] = (int)$r['s']; $money[$c]['count'] += (int)$r['n']; } ksort($money);
  $pc = $pdo->prepare('SELECT currency, COUNT(*) n, SUM(CASE WHEN status IN (\'approved\',\'paid\') THEN amount_minor ELSE 0 END) earned FROM aff_commission WHERE transaction_date BETWEEN ? AND ? GROUP BY currency'); $pc->execute([$from, $to]); $per = []; foreach ($pc->fetchAll(PDO::FETCH_ASSOC) as $r) $per[$r['currency']] = ['n' => (int)$r['n'], 'earned' => (int)$r['earned']];
  $conv = array_sum(array_column($per, 'n')); $epc = []; if ($clicks !== null && $clicks['affiliate'] > 0) foreach ($per as $c => $x) $epc[$c] = (int)round($x['earned'] / $clicks['affiliate']);   // minor units per click, rounded
  $rate = ($clicks !== null && $clicks['affiliate'] > 0 && $money) ? round($conv / $clicks['affiliate'] * 100, 2) : null;
  $tt = $pdo->prepare("SELECT c.tool_slug, c.currency, SUM(CASE WHEN c.status IN ('approved','paid') THEN c.amount_minor ELSE 0 END) earned, COUNT(*) n FROM aff_commission c WHERE c.transaction_date BETWEEN ? AND ? AND c.tool_slug <> '' GROUP BY c.tool_slug, c.currency HAVING earned > 0 ORDER BY earned DESC LIMIT 10"); $tt->execute([$from, $to]); $top = []; foreach ($tt->fetchAll(PDO::FETCH_ASSOC) as $r) $top[] = ['tool' => $r['tool_slug'], 'name' => (string)($cat[$r['tool_slug']]['name'] ?? $r['tool_slug']), 'currency' => $r['currency'], 'earned' => (int)$r['earned'], 'conversions' => (int)$r['n'], 'clicks' => $clicksAll === null ? null : ($clicksAll[$r['tool_slug']]['affiliate'] ?? 0)];
  $nt = $pdo->prepare("SELECT COALESCE(n.name, '(no network)') net, c.currency, SUM(CASE WHEN c.status IN ('approved','paid') THEN c.amount_minor ELSE 0 END) earned, COUNT(*) n FROM aff_commission c JOIN aff_partner p ON p.id = c.partner_id LEFT JOIN aff_network n ON n.id = p.network_id WHERE c.transaction_date BETWEEN ? AND ? GROUP BY net, c.currency HAVING earned > 0 ORDER BY earned DESC LIMIT 10"); $nt->execute([$from, $to]); $nets = $nt->fetchAll(PDO::FETCH_ASSOC);
  $months = []; $ym = gmdate('Y-m', strtotime($to . ' UTC')); for ($i = 11; $i >= 0; $i--) $months[] = gmdate('Y-m', strtotime($ym . '-01 UTC -' . $i . ' months')); $trend = [];
  foreach ($pdo->query("SELECT DATE_FORMAT(transaction_date, '%Y-%m') m, currency, status, SUM(amount_minor) s FROM aff_commission GROUP BY m, currency, status")->fetchAll(PDO::FETCH_ASSOC) as $r) if (in_array($r['m'], $months, true) && in_array($r['status'], ['pending', 'approved'], true)) $trend[$r['currency']][$r['m']][$r['status']] = (int)$r['s'];
  foreach ($pdo->query("SELECT DATE_FORMAT(paid_at, '%Y-%m') m, currency, SUM(amount_minor) s FROM aff_commission WHERE status = 'paid' AND paid_at IS NOT NULL GROUP BY m, currency")->fetchAll(PDO::FETCH_ASSOC) as $r) if (in_array($r['m'], $months, true)) $trend[$r['currency']][$r['m']]['received'] = (int)$r['s'];
  ksort($trend);
  return $d + ['partners' => $total, 'approved' => $by['approved'] + $by['active'], 'pending' => $by['applied'] + $by['pending'], 'monetized' => count($mon) + $legacy, 'managed_links' => count($mon), 'legacy_links' => $legacy, 'unmonetized' => max(0, count($cat) - count($mon) - $legacy), 'clicks' => $clicks, 'conversions' => $conv, 'rate' => $rate, 'money' => $money, 'epc' => $epc, 'top_tools' => $top, 'top_networks' => $nets, 'trend' => $trend, 'months' => $months, 'by_status' => $by, 'any_commissions' => (bool)$money];
}

/** The revenue-opportunity report. No estimated earnings: only recorded clicks, recorded program facts and workflow state. */
function aff_opportunities(PDO $pdo, int $days = 90, ?int $nowTs = null): array {
  [$from, $to, $days] = aff_period($days, $nowTs); $today = aff_today($nowTs); $cat = aff_catalogue(); $o = ['ready' => aff_ready($pdo), 'from' => $from, 'to' => $to, 'days' => $days];
  if (!$o['ready']) return $o + ['clicks_available' => null, 'unmonetized_top' => [], 'category_gaps' => [], 'no_conversions' => [], 'followups' => [], 'verify' => [], 'potential' => [], 'monetized_tools' => [], 'classes' => []];
  $clicks = aff_tool_clicks($pdo, $from, $to); $partners = []; foreach ($pdo->query('SELECT * FROM aff_partner')->fetchAll(PDO::FETCH_ASSOC) as $p) if ($p['tool_slug'] !== '') $partners[$p['tool_slug']][] = $p;
  $active = []; foreach ($pdo->query("SELECT l.*, p.status AS pstatus, p.company FROM aff_link l JOIN aff_partner p ON p.id = l.partner_id WHERE l.status = 'active'")->fetchAll(PDO::FETCH_ASSOC) as $l) $active[$l['tool_slug']] = $l;
  $rank = ['active' => 0, 'approved' => 1, 'pending' => 2, 'applied' => 3, 'not_applied' => 4, 'researching' => 5, 'suspended' => 6, 'expired' => 7, 'rejected' => 8]; $classes = []; $rows = [];
  foreach ($cat as $id => $t) {
    $id = (string)$id; $ps = $partners[$id] ?? []; usort($ps, fn($a, $b) => ($rank[$a['status']] ?? 9) <=> ($rank[$b['status']] ?? 9)); $best = $ps[0] ?? null; $c = $clicks[$id] ?? ['views' => 0, 'outbound' => 0, 'affiliate' => 0];
    $cls = isset($active[$id]) && in_array($active[$id]['pstatus'], ['approved', 'active'], true) ? 'monetized' : (trim((string)($t['affiliate'] ?? '')) !== '' ? 'legacy' : ($best === null ? 'none' : (in_array($best['status'], ['approved', 'active'], true) ? 'approved_no_link' : (in_array($best['status'], ['applied', 'pending'], true) ? 'pending' : (in_array($best['status'], ['researching', 'not_applied'], true) ? 'early' : 'closed')))));
    $classes[$cls] = ($classes[$cls] ?? 0) + 1; $rows[$id] = ['slug' => $id, 'name' => (string)($t['name'] ?? $id), 'category' => (string)($t['category'] ?? ''), 'class' => $cls, 'outbound' => $c['outbound'], 'affiliate' => $c['affiliate'], 'partner' => $best, 'verified' => $best && !empty($best['verified_at'])];
  }
  $un = array_filter($rows, fn($r) => $r['outbound'] > 0 && in_array($r['class'], ['none', 'early', 'closed', 'approved_no_link', 'pending'], true)); uasort($un, fn($a, $b) => $b['outbound'] <=> $a['outbound']);
  $potential = array_filter($rows, fn($r) => $r['outbound'] >= 3 && $r['class'] === 'none'); uasort($potential, fn($a, $b) => $b['outbound'] <=> $a['outbound']);
  $cg = []; foreach ($rows as $r) { $k = $r['category'] ?: '(no category)'; $cg[$k] = $cg[$k] ?? ['category' => $k, 'tools' => 0, 'outbound' => 0, 'monetized_tools' => 0, 'monetized_clicks' => 0]; $cg[$k]['tools']++; $cg[$k]['outbound'] += $r['outbound']; if (in_array($r['class'], ['monetized', 'legacy'], true)) { $cg[$k]['monetized_tools']++; $cg[$k]['monetized_clicks'] += $r['outbound']; } }
  $gaps = array_filter($cg, fn($g) => $g['outbound'] > 0 && $g['monetized_clicks'] * 5 < $g['outbound']); usort($gaps, fn($a, $b) => $b['outbound'] <=> $a['outbound']);
  $nc = []; foreach ($active as $slug => $l) { if (!in_array($l['pstatus'], ['approved', 'active'], true)) continue; $n = $pdo->prepare('SELECT COUNT(*) FROM aff_commission WHERE partner_id = ?'); $n->execute([(int)$l['partner_id']]); if ((int)$n->fetchColumn() === 0 && substr((string)$l['activated_at'], 0, 10) <= gmdate('Y-m-d', strtotime($today . ' UTC') - AFF_VERIFY_DAYS * 86400)) $nc[] = ['slug' => $slug, 'name' => $rows[$slug]['name'] ?? $slug, 'company' => $l['company'], 'since' => substr((string)$l['activated_at'], 0, 10), 'affiliate_clicks' => $clicks === null ? null : ($clicks[$slug]['affiliate'] ?? 0)]; }
  $fu = []; foreach ($pdo->query("SELECT * FROM aff_partner WHERE status IN ('applied','pending') ORDER BY applied_at")->fetchAll(PDO::FETCH_ASSOC) as $p) { $due = $p['follow_up_at'] !== null ? $p['follow_up_at'] <= $today : ($p['applied_at'] !== null && $p['applied_at'] <= gmdate('Y-m-d', strtotime($today . ' UTC') - AFF_FOLLOWUP_DAYS * 86400)); if ($due) $fu[] = ['id' => (int)$p['id'], 'company' => $p['company'], 'tool' => $p['tool_slug'], 'status' => $p['status'], 'applied_at' => $p['applied_at'], 'follow_up_at' => $p['follow_up_at']]; }
  $vf = []; foreach ($pdo->query("SELECT l.*, p.status AS pstatus, p.company FROM aff_link l JOIN aff_partner p ON p.id = l.partner_id WHERE l.status = 'active' OR l.verify_result = 'broken' ORDER BY l.id")->fetchAll(PDO::FETCH_ASSOC) as $l) {
    $why = []; if ($l['verify_result'] === 'broken') $why[] = 'reported broken'; if ($l['status'] === 'active') { if ($l['last_verified_at'] === null) $why[] = 'never verified'; elseif ($l['last_verified_at'] < gmdate('Y-m-d', strtotime($today . ' UTC') - AFF_VERIFY_DAYS * 86400)) $why[] = 'not verified for over ' . AFF_VERIFY_DAYS . ' days'; if (!in_array($l['pstatus'], ['approved', 'active'], true)) $why[] = 'partnership is ' . $l['pstatus']; if (aff_link_problems($l['url'])) $why[] = 'link fails the structure check'; }
    if ($why) $vf[] = ['id' => (int)$l['id'], 'tool' => $l['tool_slug'], 'name' => $rows[$l['tool_slug']]['name'] ?? $l['tool_slug'], 'company' => $l['company'], 'status' => $l['status'], 'why' => implode(', ', $why), 'last_verified_at' => $l['last_verified_at']]; }
  return $o + ['clicks_available' => $clicks !== null, 'unmonetized_top' => array_slice(array_values($un), 0, 20), 'category_gaps' => array_slice($gaps, 0, 15), 'no_conversions' => $nc, 'followups' => $fu, 'verify' => $vf, 'potential' => array_slice(array_values($potential), 0, 15), 'classes' => $classes, 'rows' => $rows];
}
